def compare_versions(a, b):
    def parse(v):
        v = v.split("+", 1)[0]
        core, sep, pre = v.partition("-")
        nums = [int(p) for p in core.split(".") if p != ""]
        return nums, (pre if sep else None)

    na, pa = parse(a)
    nb, pb = parse(b)
    ln = max(len(na), len(nb))
    na = na + [0] * (ln - len(na))
    nb = nb + [0] * (ln - len(nb))
    if na != nb:
        return -1 if na < nb else 1
    if pa is None and pb is None:
        return 0
    if pa is None:
        return 1
    if pb is None:
        return -1
    ia, ib = pa.split("."), pb.split(".")
    for x, y in zip(ia, ib):
        if x == y:
            continue
        xn, yn = x.isdigit(), y.isdigit()
        if xn and yn:
            return -1 if int(x) < int(y) else 1
        if xn:
            return -1
        if yn:
            return 1
        return -1 if x < y else 1
    if len(ia) == len(ib):
        return 0
    return -1 if len(ia) < len(ib) else 1
