```typescript
function normalizeRoute(path: string): string {
  let s = path.split('#')[0].split('?')[0];
  if (s === '') return '/';
  const trailing = s.length > 1 && s.endsWith('/');
  const stack: string[] = [];
  for (const seg of s.split('/')) {
    if (seg === '' || seg === '.') continue;
    if (seg === '..') {
      stack.pop();
      continue;
    }
    stack.push(seg);
  }
  let out = '/' + stack.join('/');
  if (trailing && out !== '/') out += '/';
  return out;
}
```

