std::vector<int> topKFrequent(const std::vector<int>& values, int k) {
    std::map<int, int> counts;
    for (int v : values) counts[v]++;
    std::vector<std::pair<int, int>> items;
    for (const auto& kv : counts) items.push_back({kv.second, kv.first});
    std::sort(items.begin(), items.end(), [](const std::pair<int, int>& a, const std::pair<int, int>& b) {
        if (a.first != b.first) return a.first > b.first;
        return a.second < b.second;
    });
    std::vector<int> out;
    for (int i = 0; i < k && i < (int)items.size(); i++) out.push_back(items[i].second);
    return out;
}
