std::vector<long long> rangeSums(const std::vector<long long>& values, const std::vector<std::pair<int, int>>& queries) {
    std::vector<long long> prefix(values.size() + 1, 0);
    for (size_t i = 0; i < values.size(); i++) prefix[i + 1] = prefix[i] + values[i];
    std::vector<long long> out;
    out.reserve(queries.size());
    int n = (int)values.size();
    for (const auto& q : queries) {
        int lo = q.first, hi = q.second;
        if (lo < 0 || hi >= n || lo > hi) out.push_back(0);
        else out.push_back(prefix[hi + 1] - prefix[lo]);
    }
    return out;
}
