function validatePassword(password, policy) {
  const violations = [];
  if (password.length < policy.minLength) violations.push('min length');
  if (policy.requireUpper && !/[A-Z]/.test(password)) violations.push('uppercase letter required');
  if (policy.requireDigit && !/[0-9]/.test(password)) violations.push('digit required');
  if (policy.requireSymbol && !/[^A-Za-z0-9]/.test(password.replace(/\s/g, ''))) {
    violations.push('symbol required');
  }
  const lowered = password.toLowerCase();
  if (policy.banned.some(word => word !== '' && lowered.includes(word))) violations.push('banned word');
  if (/\s/.test(password)) violations.push('whitespace not allowed');
  return violations;
}
```

