std::string minWindow(const std::string& source, const std::string& target) {
    if (target.empty()) return "";
    int need[128] = {0};
    for (char ch : target) need[static_cast<unsigned char>(ch)] += 1;
    int missing = static_cast<int>(target.size());
    int left = 0, bestStart = 0, bestLength = -1;
    for (int right = 0; right < static_cast<int>(source.size()); right++) {
        unsigned char ch = static_cast<unsigned char>(source[right]);
        if (need[ch] > 0) missing--;
        need[ch] -= 1;
        while (missing == 0) {
            int length = right - left + 1;
            if (bestLength == -1 || length < bestLength) {
                bestStart = left;
                bestLength = length;
            }
            unsigned char out = static_cast<unsigned char>(source[left]);
            need[out] += 1;
            if (need[out] > 0) missing++;
            left++;
        }
    }
    if (bestLength == -1) return "";
    return source.substr(bestStart, bestLength);
}
```

