class MinStack:
    def __init__(self):
        self.data = []
        self.mins = []

    def push(self, value):
        self.data.append(value)
        if not self.mins or value <= self.mins[-1]:
            self.mins.append(value)

    def pop(self):
        if not self.data:
            raise IndexError("empty stack")
        value = self.data.pop()
        if self.mins and self.mins[-1] == value:
            self.mins.pop()
        return value

    def top(self):
        if not self.data:
            raise IndexError("empty stack")
        return self.data[-1]

    def get_min(self):
        if not self.mins:
            raise IndexError("empty stack")
        return self.mins[-1]
