  if (RESERVED.has(name)) return false;
  for (let i = 0; i < name.length; i++) {
    const ch = name[i];
    const isLetter = (ch >= 'A' && ch <= 'Z') || (ch >= 'a' && ch <= 'z') || ch === '_' || ch === '$';
