int maxNonOverlapping(std::vector<std::pair<int,int>> intervals) {
    std::vector<std::pair<int,int>> kept;
    for (auto& interval : intervals) if (interval.first <= interval.second) kept.push_back(interval);
    std::sort(kept.begin(), kept.end(), [](const auto& a, const auto& b) {
        if (a.second != b.second) return a.second < b.second;
        return a.first < b.first;
    });
    int count = 0;
    long long lastEnd = (long long)-4e18;
    for (const auto& interval : kept) {
        if (interval.first >= lastEnd) {
            count += 1;
            lastEnd = interval.second;
        }
    }
    return count;
}
