function windowsOf<T>(items: readonly T[], size: number): T[][] {
  if (!Number.isInteger(size) || size < 1) throw new RangeError('size must be positive');
  if (size > items.length && items.length > 0) throw new RangeError('size larger than input');
  if (size > items.length) return [];
  const out: T[][] = [];
  for (let start = 0; start + size <= items.length; start++) {
    out.push(items.slice(start, start + size));
  }
  return out;
}
