function truncateMiddle(text, maxLength, ellipsis = '...') {
  if (!Number.isInteger(maxLength) || maxLength < 0) throw new RangeError('bad maxLength');
  if (text.length <= maxLength) return text;
  if (maxLength <= ellipsis.length) return ellipsis.slice(0, maxLength);
  const keep = maxLength - ellipsis.length;
  const head = Math.ceil(keep / 2);
  const tail = keep - head;
  return text.slice(0, head) + ellipsis + (tail > 0 ? text.slice(text.length - tail) : '');
}
```

