```cpp
struct Node {
    int value;
    Node* left;
    Node* right;
};

class Bst {
public:
    ~Bst() { destroy(root_); }

    void insert(int value) {
        Node** link = &root_;
        while (*link != nullptr) {
            if (value == (*link)->value) return;
            link = value < (*link)->value ? &((*link)->left) : &((*link)->right);
        }
        *link = new Node{value, nullptr, nullptr};
        count_ += 1;
    }

    bool contains(int value) const {
        const Node* node = root_;
        while (node != nullptr) {
            if (value == node->value) return true;
            node = value < node->value ? node->left : node->right;
        }
        return false;
    }

    std::vector<int> inorder() const {
        std::vector<int> out;
        std::vector<const Node*> stack;
        const Node* current = root_;
        while (current != nullptr || !stack.empty()) {
            while (current != nullptr) {
                stack.push_back(current);
                current = current->left;
            }
            current = stack.back();
            stack.pop_back();
            out.push_back(current->value);
            current = current->right;
        }
        return out;
    }

    int height() const {
        if (root_ == nullptr) return 0;
        int best = 0;
        std::vector<std::pair<const Node*,int>> stack{{root_, 1}};
        while (!stack.empty()) {
            auto [node, depth] = stack.back();
            stack.pop_back();
            if (depth > best) best = depth;
            if (node->left) stack.push_back({node->left, depth + 1});
            if (node->right) stack.push_back({node->right, depth + 1});
        }
        return best;
    }

    int size() const { return count_; }

private:
    static void destroy(Node* node) {
        if (node == nullptr) return;
        destroy(node->left);
        destroy(node->right);
        delete node;
    }
    Node* root_ = nullptr;
    int count_ = 0;
};
```

