int longestCommonSubsequence(const std::string& a, const std::string& b) {
    const int n = (int)a.size(), m = (int)b.size();
    std::vector<int> row(m + 1, 0);
    for (int i = 1; i <= n; i++) {
        int diagonal = 0;
        for (int j = 1; j <= m; j++) {
            int above = row[j];
            if (a[i - 1] == b[j - 1]) row[j] = diagonal + 1;
            else row[j] = std::max(row[j], row[j - 1]);
            diagonal = above;
        }
    }
    return row[m];
}
```

