function topologicalSort(graph: Map<string, string[]>): string[] | null {
  const indegree = new Map<string, number>();
  const ensure = (node: string) => {
    if (!indegree.has(node)) indegree.set(node, 0);
  };
  for (const [node, neighbours] of graph) {
    ensure(node);
    for (const next of neighbours) ensure(next);
  }
  for (const [, neighbours] of graph) {
    for (const next of neighbours) indegree.set(next, (indegree.get(next) as number) + 1);
  }
  const ready = [...indegree.entries()].filter(([, count]) => count === 0).map(([node]) => node);
  const order: string[] = [];
  while (ready.length > 0) {
    ready.sort();
    const node = ready.shift() as string;
    order.push(node);
    for (const next of graph.get(node) ?? []) {
      const left = (indegree.get(next) as number) - 1;
      indegree.set(next, left);
      if (left === 0) ready.push(next);
    }
  }
  return order.length === indegree.size ? order : null;
}
```

