const VALUES = { I: 1, V: 5, X: 10, L: 50, C: 100, D: 500, M: 1000 };

function romanToInt(text) {
  if (typeof text !== 'string' || text === '') throw new RangeError('empty numeral');
  const symbols = text.toUpperCase().split('');
  for (const symbol of symbols) {
    if (!Object.prototype.hasOwnProperty.call(VALUES, symbol)) {
      throw new RangeError('bad symbol: ' + symbol);
    }
  }
  let total = 0;
  for (let index = 0; index < symbols.length; index++) {
    const value = VALUES[symbols[index]];
    const next = index + 1 < symbols.length ? VALUES[symbols[index + 1]] : 0;
    total += value < next ? -value : value;
  }
  return total;
}
