function intersectSets<T>(sets: ReadonlyArray<ReadonlySet<T>>): Set<T> {
  if (sets.length === 0) return new Set<T>();
  const out = new Set<T>();
  for (const value of sets[0]) {
    if (sets.every(set => set.has(value))) out.add(value);
  }
  return out;
}

