#include <algorithm>

void rotate_array(std::vector<int>& values, int steps) {
    if (values.empty()) return;
    const int size = static_cast<int>(values.size());
    int shift = steps % size;
    if (shift < 0) shift += size;
    std::reverse(values.begin(), values.end());
    std::reverse(values.begin(), values.begin() + (size - shift));
    std::reverse(values.begin() + (size - shift), values.end());
}
