def parse_csv_line(line):
    fields = []
    current = []
    in_quotes = False
    index = 0
    while index < len(line):
        ch = line[index]
        if in_quotes:
            if ch == '"':
                if index + 1 < len(line) and line[index + 1] == '"':
                    current.append('"')
                    index += 2
                    continue
                in_quotes = False
            else:
                current.append(ch)
        elif ch == '"':
            in_quotes = True
        elif ch == ',':
            fields.append(''.join(current))
            current = []
        else:
            current.append(ch)
        index += 1
    fields.append(''.join(current))
    return fields
