function weightedPick(entries: [string, number][], r: number): string | null {
  if (!Number.isFinite(r) || r < 0 || r >= 1) return null;
  let total = 0;
  for (const [, w] of entries) total += Math.max(0, w);
  if (total <= 0) return null;
  let target = r * total;
  for (const [name, w] of entries) {
    const weight = Math.max(0, w);
    if (weight === 0) continue;
    if (target < weight) return name;
    target -= weight;
  }
  return null;
}
