def count_matches(text, pattern):
    if not pattern:
        return 0
    m = len(pattern)
    lps = [0] * m
    k = 0
    for i in range(1, m):
        while k and pattern[i] != pattern[k]:
            k = lps[k - 1]
        if pattern[i] == pattern[k]:
            k += 1
        lps[i] = k
    count = 0
    k = 0
    for ch in text:
        while k and ch != pattern[k]:
            k = lps[k - 1]
        if ch == pattern[k]:
            k += 1
        if k == m:
            count += 1
            k = lps[k - 1]
    return count
