            return (std::max(leftSmall, leftLarge) + std::min(rightSmall, rightLarge)) / 2.0;
        }
        if (leftSmall > rightLarge) hi = cutSmall - 1;
        else lo = cutSmall + 1;
    }
    return 0.0;
