std::string intToRoman(int value) {
    if (value < 1 || value > 3999) throw std::invalid_argument("out of range");
    static const std::pair<int, const char*> table[] = {
        {1000, "M"}, {900, "CM"}, {500, "D"}, {400, "CD"}, {100, "C"}, {90, "XC"},
        {50, "L"}, {40, "XL"}, {10, "X"}, {9, "IX"}, {5, "V"}, {4, "IV"}, {1, "I"}};
    std::string out;
    for (const auto& [amount, glyph] : table) {
        while (value >= amount) {
            out += glyph;
            value -= amount;
        }
    }
    return out;
}

int romanToInt(const std::string& text) {
    if (text.empty()) throw std::invalid_argument("empty numeral");
    auto digit = [](char c) -> int {
        switch (c) {
            case 'I': return 1;
            case 'V': return 5;
            case 'X': return 10;
            case 'L': return 50;
            case 'C': return 100;
            case 'D': return 500;
            case 'M': return 1000;
            default: return -1;
        }
    };
    int total = 0;
    for (size_t i = 0; i < text.size(); i++) {
        int value = digit(text[i]);
        if (value < 0) throw std::invalid_argument("bad character");
        if (i + 1 < text.size()) {
            int next = digit(text[i + 1]);
            if (next < 0) throw std::invalid_argument("bad character");
            if (value < next) {
                total += next - value;
                i++;
                continue;
            }
        }
        total += value;
    }
    if (total < 1 || total > 3999 || intToRoman(total) != text) throw std::invalid_argument("non-canonical numeral");
    return total;
}
