from collections import Counter


def min_window(source, target):
    if not target:
        return ""
    need = Counter(target)
    missing = len(target)
    left = 0
    best = None
    for right, ch in enumerate(source):
        if need[ch] > 0:
            missing -= 1
        need[ch] -= 1
        while missing == 0:
            if best is None or right - left < best[1] - best[0] - 1:
                best = (left, right + 1)
            left_ch = source[left]
            need[left_ch] += 1
            if need[left_ch] > 0:
                missing += 1
            left += 1
    if best is None:
        return ""
    return source[best[0]:best[1]]
