def valid_utf8(data):
    index = 0
    total = len(data)
    while index < total:
        lead = data[index]
        if not 0 <= lead <= 0xFF:
            return False
        if lead <= 0x7F:
            index += 1
            continue
        if 0xC2 <= lead <= 0xDF:
            count = 1
        elif 0xE0 <= lead <= 0xEF:
            count = 2
        elif 0xF0 <= lead <= 0xF4:
            count = 3
        else:
