int longestMountain(const std::vector<int>& values) {
    int n = static_cast<int>(values.size());
    int best = 0;
    int up = 0, down = 0;
    for (int i = 1; i < n; i++) {
        if (values[i] > values[i - 1]) {
            up++;
            down = 0;
        } else if (values[i] < values[i - 1] && up > 0) {
            down++;
            best = std::max(best, up + down + 1);
        } else {
            up = 0;
            down = 0;
        }
    }
    return best;
}
