function uniqueBy<T>(items: T[], keyOf: (item: T) => string, mode: 'first' | 'last' = 'first'): T[] {
  const picked = new Map<string, number>();
  for (let i = 0; i < items.length; i++) {
    const key = keyOf(items[i]);
    if (mode === 'first') {
      if (!picked.has(key)) picked.set(key, i);
    } else {
      picked.set(key, i);
    }
  }
  const keep = new Set<number>(picked.values());
  return items.filter((_, index) => keep.has(index));
}
