type Shape =
  | { kind: 'circle'; r: number }
  | { kind: 'rect'; w: number; h: number }
  | { kind: 'tri'; b: number; h: number };

function shapeArea(shape: Shape): number {
  let area: number;
  switch (shape.kind) {
    case 'circle':
      if (!(shape.r > 0)) throw new RangeError('bad dimension');
      area = Math.PI * shape.r * shape.r;
      break;
    case 'rect':
      if (!(shape.w > 0) || !(shape.h > 0)) throw new RangeError('bad dimension');
      area = shape.w * shape.h;
      break;
    case 'tri':
      if (!(shape.b > 0) || !(shape.h > 0)) throw new RangeError('bad dimension');
      area = (shape.b * shape.h) / 2;
      break;
    default: {
      const never: never = shape;
      throw new RangeError(`unknown kind ${JSON.stringify(never)}`);
    }
  }
  return Math.round(area * 100) / 100;
}
```

