def decode_varint(data):
    if not data:
        raise ValueError("empty input")
    result = 0
    shift = 0
    for index, byte in enumerate(data):
        if not 0 <= byte <= 255:
            raise ValueError("byte out of range")
        result |= (byte & 0x7F) << shift
        if not byte & 0x80:
            return result, index + 1
        shift += 7
    raise ValueError("truncated varint")
