long long stairsWays(int steps, int maxJump) {
    if (steps < 0) return 0;
    if (steps == 0) return 1;
    if (maxJump <= 0) return 0;
    std::vector<long long> dp(steps + 1, 0);
    dp[0] = 1;
    for (int total = 1; total <= steps; total++) {
        for (int jump = 1; jump <= maxJump && jump <= total; jump++) {
            dp[total] += dp[total - jump];
        }
    }
    return dp[steps];
}
