function fill(template, vars) {
  let out = '';
  let i = 0;
  while (i < template.length) {
    const ch = template[i];
    if (ch === '{' && template[i + 1] === '{') { out += '{'; i += 2; continue; }
    if (ch === '}' && template[i + 1] === '}') { out += '}'; i += 2; continue; }
    if (ch === '{') {
      const close = template.indexOf('}', i + 1);
      if (close !== -1) {
        const name = template.slice(i + 1, close);
        if (/^[A-Za-z0-9_.]+$/.test(name) && Object.prototype.hasOwnProperty.call(vars, name)) {
          out += String(vars[name]);
          i = close + 1;
          continue;
        }
      }
    }
    out += ch;
    i += 1;
  }
  return out;
}
