function memoizeLru(fn, limit = 8) {
  const cache = new Map();
  const wrapper = function (...args) {
    const key = JSON.stringify(args);
    if (cache.has(key)) {
      const value = cache.get(key);
      cache.delete(key);
      cache.set(key, value);
      return value;
    }
    const value = fn(...args);
    cache.set(key, value);
    if (cache.size > limit) {
      const oldest = cache.keys().next().value;
      cache.delete(oldest);
    }
    return value;
  };
  wrapper.cacheSize = () => cache.size;
  wrapper.clear = () => cache.clear();
  return wrapper;
}
