class EventEmitter {
  constructor() {
    this.registry = new Map();
  }

  on(name, handler) {
    const list = this.registry.get(name) ?? [];
    const entry = { handler, once: false };
    list.push(entry);
    this.registry.set(name, list);
    return () => this.off(name, handler);
  }

  once(name, handler) {
    const list = this.registry.get(name) ?? [];
    const entry = { handler, once: true };
    list.push(entry);
    this.registry.set(name, list);
    return () => this.off(name, handler);
  }

  off(name, handler) {
    const list = this.registry.get(name);
    if (!list) return false;
    const index = list.findIndex(entry => entry.handler === handler);
    if (index < 0) return false;
    list.splice(index, 1);
    if (list.length === 0) this.registry.delete(name);
    return true;
  }

  emit(name, ...args) {
    const list = this.registry.get(name);
    if (!list) return 0;
    const snapshot = list.slice();
    let called = 0;
    for (const entry of snapshot) {
      if (!list.includes(entry)) continue;
      if (entry.once) this.off(name, entry.handler);
      entry.handler(...args);
      called += 1;
    }
    return called;
  }

  listenerCount(name) {
    const list = this.registry.get(name);
    return list ? list.length : 0;
  }
}
