def utf8_truncate(text, max_bytes):
    if max_bytes < 0:
        raise ValueError("negative limit")
    used = 0
    kept = []
    for ch in text:
        size = len(ch.encode("utf-8"))
        if used + size > max_bytes:
            break
        used += size
        kept.append(ch)
    return "".join(kept)
