def eval_rpn(tokens):
    if not tokens:
        raise ValueError("empty expression")
    stack = []
    for token in tokens:
        if isinstance(token, int):
            stack.append(token)
            continue
        if len(stack) < 2:
            raise ValueError("missing operands")
        right = stack.pop()
        left = stack.pop()
        if token == "+":
            stack.append(left + right)
        elif token == "-":
            stack.append(left - right)
        elif token == "*":
            stack.append(left * right)
        elif token == "/":
            if right == 0:
                raise ValueError("division by zero")
            quotient = abs(left) // abs(right)
            stack.append(quotient if (left >= 0) == (right >= 0) else -quotient)
        else:
            raise ValueError("unknown operator")
    if len(stack) != 1:
        raise ValueError("leftover values")
    return stack[0]
