function flattenObject(value) {
  const out = {};
  const walk = (node, prefix) => {
    for (const key of Object.keys(node)) {
      const next = node[key];
      const path = prefix === '' ? key : prefix + '.' + key;
      const isPlain = next !== null && typeof next === 'object' && !Array.isArray(next);
      if (isPlain) walk(next, path);
      else out[path] = next;
    }
  };
  walk(value, '');
  return out;
}
