function deepFreeze<T>(value: T): T {
  const seen = new Set<object>();
  const walk = (node: any) => {
    if (node === null || typeof node !== 'object') return;
    if (seen.has(node)) return;
    seen.add(node);
    const isPlain = Array.isArray(node) || Object.getPrototypeOf(node) === Object.prototype || Object.getPrototypeOf(node) === null;
    if (!isPlain) return;
    if (Object.isFrozen(node)) return;
    Object.freeze(node);
    for (const key of Object.keys(node)) walk(node[key]);
  };
  walk(value);
  return value;
}
```

