```typescript
function comparatorFor<T>(field: keyof T, direction: 'asc' | 'desc' = 'asc'): (a: T, b: T) => number {
  if (direction !== 'asc' && direction !== 'desc') throw new RangeError('bad direction');
  return (a: T, b: T) => {
    const left = a[field] as unknown;
    const right = b[field] as unknown;
    const leftMissing = left === null || left === undefined;
    const rightMissing = right === null || right === undefined;
    if (leftMissing && rightMissing) return 0;
    if (leftMissing) return 1;
    if (rightMissing) return -1;
    let order: number;
    if (typeof left === 'string' && typeof right === 'string') {
      const compared = left.localeCompare(right);
      order = compared === 0 ? 0 : compared < 0 ? -1 : 1;
    } else if (left === right) {
      order = 0;
    } else {
      order = (left as number) < (right as number) ? -1 : 1;
    }
    return direction === 'desc' ? -order : order;
  };
}
```

