```javascript
function roundRobin(tasks, quantum) {
  if (!(quantum >= 1)) throw new RangeError('quantum must be at least 1');
  const queue = tasks.filter(task => task.time > 0).map(task => ({ name: task.name, time: task.time }));
  const visits = [];
  let total = 0;
  while (queue.length > 0) {
    const task = queue.shift();
    const ran = Math.min(quantum, task.time);
    visits.push([task.name, ran]);
    total += ran;
    task.time -= ran;
    if (task.time > 0) queue.push(task);
  }
  visits.push(['done', total]);
  return visits;
}
```

