function setPath(object, path, value) {
  if (typeof path !== 'string' || path === '') throw new RangeError('path must not be empty');
  const parts = path.split('.');
  const clone = node => (Array.isArray(node) ? node.slice() : { ...node });
  const root = clone(object === null || typeof object !== 'object' ? {} : object);
  let node = root;
  for (let i = 0; i < parts.length - 1; i++) {
    const key = parts[i];
    const next = node[key];
    node[key] = next !== null && typeof next === 'object' ? clone(next) : {};
    node = node[key];
  }
  node[parts[parts.length - 1]] = value;
  return root;
}
