assert.deepEqual(shapeArea({kind: 'rect', width: 1.5, height: 2}), 3);
assert.deepEqual(Math.round(shapeArea({kind: 'circle', radius: 1}) * 100) / 100, 3.14);
assert.deepEqual(shapeArea({kind: 'triangle', base: 1, height: 1}), 0.5);
