bool insidePolygon(const std::vector<std::pair<int,int>>& polygon, int x, int y) {
    const int n = (int)polygon.size();
    if (n < 3) return false;
    bool inside = false;
    for (int i = 0, j = n - 1; i < n; j = i++) {
        long long xi = polygon[i].first, yi = polygon[i].second;
        long long xj = polygon[j].first, yj = polygon[j].second;
        bool crosses = (yi > y) != (yj > y);
        if (crosses) {
            double atX = (double)(xj - xi) * (double)(y - yi) / (double)(yj - yi) + (double)xi;
            if ((double)x < atX) inside = !inside;
        }
    }
    return inside;
}
```

