def _trim(coefficients):
    end = len(coefficients)
    while end > 0 and coefficients[end - 1] == 0:
        end -= 1
    return coefficients[:end]


def poly_add(a, b):
    size = max(len(a), len(b))
    out = [0] * size
    for index in range(size):
        out[index] = (a[index] if index < len(a) else 0) + (b[index] if index < len(b) else 0)
    return _trim(out)


def poly_mul(a, b):
    if not a or not b:
        return []
    out = [0] * (len(a) + len(b) - 1)
    for i, left in enumerate(a):
        if left == 0:
            continue
        for j, right in enumerate(b):
            out[i + j] += left * right
    return _trim(out)
```

```python
import math


class Fraction:
    def __init__(self, numerator, denominator=1):
        if denominator == 0:
            raise ZeroDivisionError("zero denominator")
        if denominator < 0:
            numerator, denominator = -numerator, -denominator
        common = math.gcd(abs(numerator), denominator) or 1
        self.numerator = numerator // common
        self.denominator = denominator // common

    def _coerce(self, other):
        return other if isinstance(other, Fraction) else Fraction(other)

    def __add__(self, other):
        other = self._coerce(other)
        return Fraction(self.numerator * other.denominator + other.numerator * self.denominator,
                        self.denominator * other.denominator)

    def __sub__(self, other):
        other = self._coerce(other)
        return Fraction(self.numerator * other.denominator - other.numerator * self.denominator,
                        self.denominator * other.denominator)

    def __mul__(self, other):
        other = self._coerce(other)
        return Fraction(self.numerator * other.numerator, self.denominator * other.denominator)

    def __truediv__(self, other):
        other = self._coerce(other)
        return Fraction(self.numerator * other.denominator, self.denominator * other.numerator)

    def __eq__(self, other):
        if not isinstance(other, Fraction):
            return NotImplemented
        return self.numerator == other.numerator and self.denominator == other.denominator

    def __hash__(self):
        return hash((self.numerator, self.denominator))

    def __str__(self):
        if self.denominator == 1:
            return str(self.numerator)
        return str(self.numerator) + "/" + str(self.denominator)
