class BitSet {
  constructor(capacity) {
    if (!Number.isInteger(capacity) || capacity < 0) throw new RangeError('bad capacity');
    this.capacity = capacity;
    this.words = new Uint8Array(Math.ceil(capacity / 8));
  }

  check(value) {
    if (!Number.isInteger(value) || value < 0 || value >= this.capacity) throw new RangeError('bit out of range');
  }

  add(value) {
    this.check(value);
    this.words[value >> 3] |= 1 << (value & 7);
  }

  remove(value) {
    this.check(value);
    this.words[value >> 3] &= ~(1 << (value & 7));
  }

  has(value) {
    if (!Number.isInteger(value) || value < 0 || value >= this.capacity) return false;
    return (this.words[value >> 3] & (1 << (value & 7))) !== 0;
  }

  count() {
    let total = 0;
    for (const word of this.words) {
      let bits = word;
      while (bits) {
        total += bits & 1;
        bits >>= 1;
      }
    }
    return total;
  }

  values() {
    const out = [];
    for (let value = 0; value < this.capacity; value++) if (this.has(value)) out.push(value);
    return out;
  }
}
