class TaskQueue {
  constructor(maxAttempts = 2) {
    if (!Number.isInteger(maxAttempts) || maxAttempts < 1) throw new RangeError('bad attempts');
    this.maxAttempts = maxAttempts;
    this.tasks = [];
  }

  add(name, run) {
    this.tasks.push({ name, run });
    return this;
  }

  run() {
    const log = [];
    for (const task of this.tasks) {
      let attempt = 0;
      let succeeded = false;
      while (attempt < this.maxAttempts && !succeeded) {
        attempt += 1;
        try {
          task.run();
          succeeded = true;
        } catch (error) {
          succeeded = false;
        }
        log.push(task.name + ':' + attempt + ':' + (succeeded ? 'ok' : 'fail'));
      }
    }
    return log;
  }
}
