function roundHalfEven(value, digits = 0) {
  if (!Number.isFinite(value)) throw new TypeError('finite numbers expected');
  if (!Number.isInteger(digits) || digits < 0 || digits > 6) throw new RangeError('digits out of range');
  const factor = 10 ** digits;
  const scaled = value * factor;
  const floor = Math.floor(scaled);
  const remainder = scaled - floor;
  let rounded;
  if (remainder > 0.5) rounded = floor + 1;
  else if (remainder < 0.5) rounded = floor;
  else rounded = floor % 2 === 0 ? floor : floor + 1;
  return rounded / factor;
}
