def count_palindrome_partitions(text):
    size = len(text)
    if size == 0:
        return 1
    is_palindrome = [[False] * size for _ in range(size)]
    for end in range(size):
        for start in range(end + 1):
            if text[start] == text[end] and (end - start <= 2 or is_palindrome[start + 1][end - 1]):
                is_palindrome[start][end] = True
    ways = [0] * (size + 1)
    ways[0] = 1
    for end in range(1, size + 1):
        for start in range(end):
            if is_palindrome[start][end - 1]:
                ways[end] += ways[start]
    return ways[size]
