function normalise(path) {
  const parts = [];
  for (const segment of path.split('/')) {
    if (segment === '' || segment === '.') continue;
    if (segment === '..') {
      parts.pop();
      continue;
    }
    parts.push(segment);
  }
  return '/' + parts.join('/');
}

function resolvePath(base, relative) {
  if (relative.startsWith('/')) return normalise(relative);
  return normalise(base + '/' + relative);
}
