def _decode(part):
    out = []
    index = 0
    while index < len(part):
        ch = part[index]
        if ch == '+':
            out.append(' ')
            index += 1
            continue
        if ch == '%':
            chunk = part[index + 1:index + 3]
            if len(chunk) != 2:
                raise ValueError("truncated escape")
            try:
                out.append(chr(int(chunk, 16)))
            except ValueError:
                raise ValueError("bad escape")
