function evaluateRPN(expression) {
  const tokens = expression.split(' ').filter(token => token !== '');
  const stack = [];
  for (const token of tokens) {
    if (!/^-?\d+$/.test(token)) {
      if (!['+', '-', '*', '/'].includes(token)) throw new RangeError('bad token: ' + token);
      if (stack.length < 2) throw new RangeError('too few operands');
      const right = stack.pop();
      const left = stack.pop();
      if (token === '+') stack.push(left + right);
      else if (token === '-') stack.push(left - right);
      else if (token === '*') stack.push(left * right);
      else {
        if (right === 0) throw new RangeError('division by zero');
        stack.push(Math.trunc(left / right));
      }
      continue;
    }
    stack.push(Number(token));
  }
  if (stack.length > 1) throw new RangeError('leftover operands');
  return stack.length === 0 ? 0 : stack[0];
}
