type Shape =
  | { kind: 'circle'; radius: number }
  | { kind: 'rect'; width: number; height: number }
  | { kind: 'triangle'; base: number; height: number };

function assertNever(value: never): never {
  throw new Error('unknown shape: ' + JSON.stringify(value));
}

function area(shape: Shape): number {
  switch (shape.kind) {
    case 'circle':
      if (shape.radius < 0) throw new RangeError('negative radius');
      return Math.PI * shape.radius ** 2;
    case 'rect':
      if (shape.width < 0 || shape.height < 0) throw new RangeError('negative side');
      return shape.width * shape.height;
    case 'triangle':
      if (shape.base < 0 || shape.height < 0) throw new RangeError('negative side');
      return 0.5 * shape.base * shape.height;
    default:
      return assertNever(shape);
  }
}

function describe(shape: Shape): string {
  switch (shape.kind) {
    case 'circle':
      return 'circle';
    case 'rect':
      return 'rect';
    case 'triangle':
      return 'triangle';
    default:
      return assertNever(shape);
  }
}
