function pipe<T>(value: T, steps: ReadonlyArray<(input: any) => any>): any {
  let current: any = value;
  for (const step of steps) current = step(current);
  return current;
}

function compose(steps: ReadonlyArray<(input: any) => any>): (value: any) => any {
  return (value: any) => pipe(value, [...steps].reverse());
}
