type Config = { port: number; debug: boolean; name: string };

function parseConfig(env: Record<string, string | undefined>): Config {
  const rawPort = (env.PORT ?? '').trim();
  const port = rawPort === '' ? 8080 : Number(rawPort);
  if (!Number.isInteger(port) || port < 1 || port > 65535) throw new RangeError('bad port: ' + rawPort);
  const rawDebug = (env.DEBUG ?? '').trim().toLowerCase();
  const debug = rawDebug === '1' || rawDebug === 'true' || rawDebug === 'yes';
  const rawName = (env.NAME ?? '').trim();
  const name = rawName === '' ? 'app' : rawName;
  if (name === '') throw new RangeError('empty name');
  return { port, debug, name };
}
