type Email = string & { readonly __brand: 'Email' };

function parseEmail(raw: string): Email {
  const normalised = raw.trim().toLowerCase();
  if (normalised.split('@').length !== 2 || normalised.includes(' ')) throw new RangeError('bad email');
  const [local, domain] = normalised.split('@');
  if (!local || !domain || !domain.includes('.') || domain.startsWith('.') || domain.endsWith('.')) {
    throw new RangeError('bad email: ' + normalised);
  }
  return normalised as Email;
}

function maskEmail(email: Email): string {
  const [local, domain] = email.split('@');
  return local[0] + '***@' + domain;
}

function domainOf(email: Email): string {
  return email.split('@')[1];
}
