interface TreeNode {
  value: number;
  children?: TreeNode[];
}

function flattenTree(root: TreeNode | null): number[] {
  if (root === null) return [];
  const out: number[] = [];
  const stack: TreeNode[] = [root];
  while (stack.length > 0) {
    const node = stack.pop()!;
    out.push(node.value);
    const kids = node.children ?? [];
    for (let index = kids.length - 1; index >= 0; index -= 1) stack.push(kids[index]);
  }
  return out;
}
```

