std::vector<std::string> rle(const std::string& text) {
    std::vector<std::string> out;
    std::size_t index = 0;
    while (index < text.size()) {
        std::size_t run = 1;
        while (index + run < text.size() && text[index + run] == text[index]) ++run;
        out.push_back(std::string(1, text[index]) + std::to_string(run));
        index += run;
    }
    return out;
}
