int count_primes(int limit) {
    int count = 0;
    for (int candidate = 2; candidate < limit; ++candidate) {
        bool prime = true;
        for (int divisor = 2; divisor * divisor <= candidate; ++divisor) {
            if (candidate % divisor == 0) {
