```python
def evaluate(tokens):
    stack = []
    for token in tokens:
        if token in ('+', '-', '*', '/'):
            if len(stack) < 2:
                raise ValueError("not enough operands")
            right = stack.pop()
            left = stack.pop()
            if token == '+':
                stack.append(left + right)
            elif token == '-':
                stack.append(left - right)
            elif token == '*':
                stack.append(left * right)
            else:
                if right == 0:
                    raise ValueError("division by zero")
                stack.append(int(left / right))
        else:
            stack.append(int(token))
    if len(stack) != 1:
        raise ValueError("malformed expression")
    return stack[0]
```

