"""Applying stock movements."""


class StockError(ValueError):
    """Raised when a movement is impossible."""


def apply_moves(quantities, moves):
    """Return a new {sku: qty} dict after applying `(sku, delta)` moves in order.

    Raises StockError for an unknown SKU or when a quantity would go negative. The caller's
    dict is never modified.
    """
    out = quantities
    for sku, delta in moves:
        if sku not in out:
            raise StockError("unknown sku: %s" % sku)
        updated = out[sku] + delta
        if updated < 0:
            raise StockError("negative stock for %s" % sku)
