"""Segment-based route matching."""


def _segments(path):
    """Non-empty path segments; a leading or trailing slash adds no segment."""
    return path.split("/")[1:]


def match(pattern, path):
    """Return a dict of `:param` values when `path` matches `pattern`, else None."""
    pattern_parts = _segments(pattern)
    path_parts = _segments(path)
    if len(pattern_parts) != len(path_parts):
        return None
    params = {}
    for expected, actual in zip(pattern_parts, path_parts):
        if expected.startswith(":"):
            if not expected[1:]:
                return None
            params[expected[1:]] = actual
        elif expected != actual:
            return None
    return params

