files.sharding/ring.py:
"""A small consistent-hash ring."""
import bisect
import hashlib


def _hash(key):
    """Stable 128-bit hash of a string."""
    return int(hashlib.sha256(key.encode("utf-8")).hexdigest(), 16)


def build_ring(nodes, replicas=3):
    """Return a sorted list of (hash, node) ring points."""
    points = []
    for node in nodes:
        for replica in range(replicas):
            points.append((_hash("%s#%d" % (node, replica)), node))
    points.sort()
    return points


def owner(ring, key):
    """The node owning `key`: the first ring point at or after its hash, wrapping around."""
    if not ring:
        return None
    position = bisect.bisect_left(ring, (_hash(key), "")) - 1
    return ring[position][1]

files.metrics/percentile.py:
"""Linear-interpolated percentiles."""


def percentile(values, p):
    """The p-th percentile (0..100) of `values` using linear interpolation."""
    if not values:
        raise ValueError("percentile of empty input")
    if not 0 <= p <= 100:
        raise ValueError("p must be between 0 and 100")
    data = sorted(values)
    if len(data) == 1:
        return float(data[0])
    rank = len(data) * p / 100.0
    lower = int(rank)
    upper = min(lower + 1, len(data) - 1)
    fraction = rank - lower
    return data[lower] + (data[upper] - data[lower]) * fraction

