def allowed_events(timestamps, limit, window_ms):
    """Return one boolean per timestamp: whether that request is allowed.

    Timestamps are non-decreasing integers in milliseconds. A request counts against the
    limit while it is younger than `window_ms`.
    """
    if limit <= 0:
        return [False] * len(timestamps)
    recent = []
    out = []
    for ts in timestamps:
        while recent and ts - recent[0] > window_ms:
            recent.pop(0)
        if len(recent) < limit:
            recent.append(ts)
            out.append(True)
        else:
            out.append(False)
    return out

