"""Expiring key/value storage."""


class TTLCache:
    """A cache where every entry carries an absolute expiry timestamp."""

    def __init__(self):
        self._data = {}

    def set(self, key, value, expires_at):
        """Store `value` until `expires_at` (inclusive instant of expiry is already stale)."""
        self._data[key] = (value, expires_at)

    def get(self, key, now):
        """Return the live value for `key`, or None when absent or expired."""
        entry = self._data.get(key)
        if entry is None:
            return None
        value, expires_at = entry
        if now > expires_at:
            del self._data[key]
            return None
        return value

    def size(self):
        """Number of entries still stored (expired ones are only dropped on access)."""
        return len(self._data)

