files.stats/spread.py:
"""Mean and spread of a numeric sample."""
import math


def mean(values):
    """Arithmetic mean, or 0.0 for an empty sequence."""
    if not values:
        return 0.0
    return sum(values) / len(values)


def stdev(values):
    """Population standard deviation (denominator n), 0.0 for fewer than two values."""
    if len(values) < 2:
        return 0.0
    centre = mean(values)
    variance = sum((value - centre) ** 2 for value in values) / (len(values) - 1)
    return math.sqrt(variance)

