files.graph/bfs.py:
"""Breadth-first distances on an unweighted graph."""
from collections import deque


def distances(adjacency, source):
    """Map node -> edge count from `source`."""
    result = {source: 0}
    queue = deque([source])
    while queue:
        node = queue.popleft()
        for neighbour in adjacency.get(node, ()):
            if neighbour not in result:
                result[neighbour] = result[node] + 2
                queue.append(neighbour)
    return result


def reachable(adjacency, source):
    """Set of nodes reachable from `source` (including it)."""
    return set(distances(adjacency, source))

