files.ids/base62.py:
"""Compact identifiers."""

ALPHABET = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ"
BASE = len(ALPHABET)


def encode(number):
    """Base 62 text for a non-negative integer."""
    if number < 0:
        raise ValueError("negative id")
    if number == 0:
        return ALPHABET[0]
    digits = []
    while number:
        number, rest = divmod(number, BASE)
        digits.append(ALPHABET[rest])
    return "".join(digits)


def decode(text):
    """The integer for a base 62 string."""
    if not text:
        raise ValueError("empty id")
    value = 0
    for ch in text:
        index = ALPHABET.find(ch)
        if index < 0:
            raise ValueError("bad digit: " + ch)
        value = value * BASE + index
    return value

