RANK = {"viewer": 1, "editor": 2, "admin": 3}


def has_permission(role, required):
    """Whether the role reaches the required level."""
    if role not in RANK or required not in RANK:
        raise ValueError("unknown role")
    return RANK[role] == RANK[required]


def highest(roles):
    """The strongest role in the collection, or None."""
    best = None
    for role in roles:
        if role not in RANK:
            raise ValueError("unknown role: " + role)
        if best is None or RANK[role] > RANK[best]:
            best = role
    return best

