def to_base(number, base):
    """Text for a non-negative integer in the given base (2..36)."""
    if not 2 <= base <= 36:
        raise ValueError("base out of range")
    if number < 0:
        raise ValueError("negative number")
    if number == 0:
        return "0"
    out = []
    while number:
        number, rest = divmod(number, base)
        out.append(DIGITS[rest])
    return "".join(out)


