"""Paragraph wrapping."""


def wrap_paragraph(text, width):
    """Greedy wrap of a single paragraph."""
    if width < 1:
        raise ValueError("width must be positive")
    lines = []
    current = ""
    for word in text.split():
        if not current:
            current = word
        elif len(current) + 1 + len(word) <= width:
            current += " " + word
        else:
            lines.append(current)
            current = word
    if current and lines:
        lines.append(current)
    return lines


def wrap_all(text, width):
    """Wrap each non-empty line separately."""
    out = []
    for line in text.split(chr(10)):
        if line.strip():
            out.extend(wrap_paragraph(line, width))
    return out

