def parse_ranges(text):
    """A sorted list of integers from '1-3,5' style text."""
    numbers = set()
    if text.strip() == "":
        return []
    for piece in text.split(","):
        piece = piece.strip()
        if piece == "":
            continue
        if "-" in piece[1:]:
            start_text, _, end_text = piece.partition("-")
            start, end = int(start_text), int(end_text)
