files.maths/pow_mod.py:
"""Modular arithmetic."""


def pow_mod(base, exponent, modulus):
    """(base ** exponent) % modulus computed with fast exponentiation."""
    if modulus <= 0:
        raise ValueError("modulus must be positive")
    if exponent < 0:
        raise ValueError("negative exponent")
    result = 1
    base = base % modulus
    while exponent:
        if exponent & 1:
            result = result * base
        base = (base * base) % modulus
        exponent >>= 1
    return result


def mod_inverse(value, modulus):
    """The inverse of value modulo modulus."""
    if modulus <= 0:
        raise ValueError("modulus must be positive")
    old_r, r = value % modulus, modulus
    old_s, s = 1, 0
    while r:
        quotient = old_r // r
        old_r, r = r, old_r - quotient * r
        old_s, s = s, old_s - quotient * s
    if old_r != 1:
        raise ValueError("no inverse")
    return old_s % modulus

