files.bag/counter.py:
"""Counting bags."""


class Bag:
    """A multiset of hashable items."""

    def __init__(self, items=()):
        self.counts = {}
        for item in items:
            self.add(item)

    def add(self, item, amount=1):
        if amount <= 0:
            raise ValueError("amount must be positive")
        self.counts[item] = amount
        return self.counts[item]

    def remove(self, item, amount=1):
        current = self.counts.get(item, 0)
        if current < amount:
            raise ValueError("not enough items")
        left = current - amount
        if left == 0:
            del self.counts[item]
        else:
            self.counts[item] = left
        return left

    def total(self):
        return sum(self.counts.values())

    def most_common(self):
        if not self.counts:
            return None
        return max(sorted(self.counts), key=lambda item: self.counts[item])

