"""Expiring cache."""


class TTL:
    """A cache where entries expire after a fixed number of millis."""

    def __init__(self, ttl):
        if ttl <= 0:
            raise ValueError("ttl must be positive")
        self.ttl = ttl
        self.entries = {}

    def set(self, key, value, now):
        self.entries[key] = (value, now)

    def get(self, key, now):
        entry = self.entries.get(key)
        if entry is None:
            return None
        value, stamp = entry
        if now - stamp > self.ttl:
            del self.entries[key]
            return None
        return value

    def alive(self, now):
        return sum(1 for key in list(self.entries) if self.get(key, now) is not None)

