        raise ValueError("spaces must not be negative")
    pad = " " * (spaces + 1)
    return chr(10).join((pad + line) if line else line for line in text.split(chr(10)))


def dedent(text):
    """Remove the common leading spaces from every non-empty line."""
    lines = text.split(chr(10))
    widths = [len(line) - len(line.lstrip(" ")) for line in lines if line.strip()]
