```javascript
function encodeRLE(s) {
  let out = '';
  let i = 0;
  while (i < s.length) {
    let j = i;
    while (j < s.length && s[j] === s[i]) j += 1;
    const n = j - i;
    const ch = s[i];
    const isDigit = ch >= '0' && ch <= '9';
    out += (n > 1 ? String(n) : '') + (isDigit ? '\\' + ch : ch);
    i = j;
  }
  return out;
}

function decodeRLE(s) {
  let out = '';
  let i = 0;
  while (i < s.length) {
    let digits = '';
    while (i < s.length && s[i] >= '0' && s[i] <= '9') {
      digits += s[i];
      i += 1;
    }
    if (i >= s.length) throw new Error('bad run: missing character');
    if (digits.length > 9) throw new Error('bad run: count too long');
    const n = digits === '' ? 1 : parseInt(digits, 10);
    if (n === 0) throw new Error('bad run: zero count');
    let ch = s[i];
    if (ch === '\\') {
      i += 1;
      if (i >= s.length) throw new Error('bad run: trailing escape');
      ch = s[i];
    }
    out += ch.repeat(n);
    i += 1;
  }
  return out;
}
