long long countInversions(std::vector<int> values) {
    int n = (int)values.size();
    std::function<long long(int, int)> sortCount = [&](int lo, int hi) -> long long {
        if (hi - lo < 2) return 0;
        int mid = lo + (hi - lo) / 2;
        long long total = sortCount(lo, mid) + sortCount(mid, hi);
        std::vector<int> tmp;
        tmp.reserve(hi - lo);
        int i = lo, j = mid;
        while (i < mid && j < hi) {
            if (values[i] <= values[j]) {
                tmp.push_back(values[i++]);
            } else {
                total += mid - i;
                tmp.push_back(values[j++]);
            }
        }
        while (i < mid) tmp.push_back(values[i++]);
        while (j < hi) tmp.push_back(values[j++]);
        for (int k = lo; k < hi; k++) values[k] = tmp[k - lo];
        return total;
    };
    return sortCount(0, n);
}
