def eval_expr(s):
    pos = [0]

    def peek():
        while pos[0] < len(s) and s[pos[0]] == " ":
            pos[0] += 1
        return s[pos[0]] if pos[0] < len(s) else ""

    def parse_expr():
        value = parse_term()
        while True:
            ch = peek()
            if ch != "+" and ch != "-":
                return value
            pos[0] += 1
            rhs = parse_term()
            value = value + rhs if ch == "+" else value - rhs

    def parse_term():
        value = parse_factor()
        while True:
            ch = peek()
            if ch != "*" and ch != "/":
                return value
            pos[0] += 1
            rhs = parse_factor()
            if ch == "*":
                value *= rhs
            else:
                if rhs == 0:
                    raise ValueError("division by zero")
                quotient = abs(value) // abs(rhs)
                value = quotient if (value < 0) == (rhs < 0) else -quotient

    def parse_factor():
        ch = peek()
        if ch == "-":
            pos[0] += 1
            return -parse_factor()
        if ch == "+":
            pos[0] += 1
            return parse_factor()
        if ch == "(":
            pos[0] += 1
            value = parse_expr()
            if peek() != ")":
                raise ValueError("expected )")
            pos[0] += 1
            return value
        start = pos[0]
        while pos[0] < len(s) and s[pos[0]].isdigit():
            pos[0] += 1
        if start == pos[0]:
            raise ValueError("expected a number")
        return int(s[start:pos[0]])

    if not s.strip():
        raise ValueError("empty expression")
    result = parse_expr()
    if peek() != "":
        raise ValueError("trailing input")
    return result
