def cheapest_flight(n, flights, src, dst, max_stops):
    if max_stops < 0 or not (0 <= src < n) or not (0 <= dst < n):
        return -1
    INF = float("inf")
    dist = [INF] * n
    dist[src] = 0
    for _ in range(max_stops + 1):
        nxt = dist[:]
        for u, v, price in flights:
            if 0 <= u < n and 0 <= v < n and dist[u] + price < nxt[v]:
                nxt[v] = dist[u] + price
        if nxt == dist:
            break
        dist = nxt
    return -1 if dist[dst] == INF else dist[dst]
