function isPlain(v) {
  return v !== null && typeof v === 'object' && !Array.isArray(v);
}

function same(a, b) {
  if (a === b) return true;
  if (Array.isArray(a) && Array.isArray(b)) {
    if (a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) if (!same(a[i], b[i])) return false;
    return true;
  }
  if (isPlain(a) && isPlain(b)) {
    const ka = Object.keys(a).filter(k => a[k] !== undefined);
    const kb = Object.keys(b).filter(k => b[k] !== undefined);
    if (ka.length !== kb.length) return false;
    for (const k of ka) if (!same(a[k], b[k])) return false;
    return true;
  }
  return false;
}

function diffObjects(before, after) {
  const out = [];
  const walk = (a, b, path) => {
    const ka = new Set(Object.keys(a).filter(k => a[k] !== undefined));
    const kb = new Set(Object.keys(b).filter(k => b[k] !== undefined));
    const keys = Array.from(new Set([...ka, ...kb])).sort();
    for (const key of keys) {
      const full = path ? path + '.' + key : key;
      const inA = ka.has(key);
      const inB = kb.has(key);
      if (inA && !inB) out.push({ path: full, kind: 'remove', from: a[key] });
      else if (!inA && inB) out.push({ path: full, kind: 'add', to: b[key] });
      else if (isPlain(a[key]) && isPlain(b[key])) walk(a[key], b[key], full);
      else if (!same(a[key], b[key])) out.push({ path: full, kind: 'change', from: a[key], to: b[key] });
    }
  };
  walk(before, after, '');
  return out;
}
