const UNIT_MS: Record<string, number> = { d: 86400000, h: 3600000, m: 60000, s: 1000, ms: 1 };

function parseDuration(text: string): number {
  if (text === '') throw new Error('bad duration: empty');
  const pattern = /(\d+)(ms|d|h|m|s)/g;
  let total = 0;
  let position = 0;
  let previous = Number.POSITIVE_INFINITY;
  let match: RegExpExecArray | null;
  while ((match = pattern.exec(text)) !== null) {
    if (match.index !== position) throw new Error('bad duration: ' + text);
    const amount = Number(match[1]);
    const unit = UNIT_MS[match[2]];
    if (amount <= 0 || unit >= previous) throw new Error('bad duration: ' + text);
    previous = unit;
    total += amount * unit;
    position = pattern.lastIndex;
  }
  if (position !== text.length) throw new Error('bad duration: ' + text);
  return total;
}
