std::string fractionToDecimal(long long numerator, long long denominator) {
    if (numerator == 0) return "0";
    bool negative = (numerator < 0) != (denominator < 0);
    unsigned long long num = numerator < 0 ? (unsigned long long)(-(numerator + 1)) + 1 : (unsigned long long)numerator;
    unsigned long long den = denominator < 0 ? (unsigned long long)(-(denominator + 1)) + 1 : (unsigned long long)denominator;
    std::string out = negative ? "-" : "";
    out += std::to_string(num / den);
    unsigned long long rem = num % den;
    if (rem == 0) return out;
    out += ".";
    std::unordered_map<unsigned long long, int> seen;
    std::string digits;
    while (rem != 0) {
        auto it = seen.find(rem);
        if (it != seen.end()) {
            digits.insert(digits.begin() + it->second, '(');
            digits += ")";
            break;
        }
        seen[rem] = (int)digits.size();
        rem *= 10;
        digits += char('0' + (int)(rem / den));
        rem %= den;
    }
    return out + digits;
}
