std::vector<long long> dijkstra(int n, const std::vector<std::vector<std::pair<int, int>>>& graph, int source) {
    const long long INF = (long long)4e18;
    std::vector<long long> dist(n, INF);
    if (source < 0 || source >= n) {
        std::vector<long long> out(n, -1);
        return out;
    }
    dist[source] = 0;
    using Item = std::pair<long long, int>;
    std::priority_queue<Item, std::vector<Item>, std::greater<Item>> pq;
    pq.push({0, source});
    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();
        if (d != dist[u]) continue;
        if (u >= (int)graph.size()) continue;
        for (const auto& edge : graph[u]) {
            int v = edge.first;
            int w = edge.second;
            if (v < 0 || v >= n) continue;
            if (d + w < dist[v]) {
                dist[v] = d + w;
                pq.push({dist[v], v});
            }
        }
    }
    std::vector<long long> out(n, -1);
    for (int i = 0; i < n; i++) if (dist[i] != INF) out[i] = dist[i];
    return out;
}
