static bool parseSemver(const std::string& text, int out[3]) {
    std::string core = text.substr(0, text.find_first_of("-+"));
    int part = 0;
    size_t pos = 0;
    while (part < 3 && pos < core.size()) {
        size_t start = pos;
        while (pos < core.size() && std::isdigit((unsigned char)core[pos])) pos++;
        if (start == pos) return false;
        out[part++] = std::stoi(core.substr(start, pos - start));
        if (part < 3) {
            if (pos >= core.size() || core[pos] != '.') return false;
            pos++;
        }
    }
    return part == 3;
}

static int compareSemver(const int a[3], const int b[3]) {
    for (int i = 0; i < 3; i++) {
        if (a[i] != b[i]) return a[i] < b[i] ? -1 : 1;
    }
    return 0;
}

bool semverSatisfies(const std::string& version, const std::string& range) {
    int ver[3];
    if (!parseSemver(version, ver)) throw std::invalid_argument("bad version: " + version);
    std::string trimmed = range;
    size_t begin = trimmed.find_first_not_of(' ');
    if (begin == std::string::npos) throw std::invalid_argument("empty range");
    size_t pos = begin;
    while (pos < trimmed.size()) {
        size_t space = trimmed.find(' ', pos);
        std::string token = trimmed.substr(pos, space == std::string::npos ? std::string::npos : space - pos);
        pos = space == std::string::npos ? trimmed.size() : space + 1;
        std::string op;
        for (const char* candidate : {">=", "<=", ">", "<", "=", "^", "~"}) {
            if (token.rfind(candidate, 0) == 0) {
                op = candidate;
                token = token.substr(op.size());
                break;
            }
        }
        int want[3];
        if (!parseSemver(token, want)) throw std::invalid_argument("bad comparator: " + token);
        int cmp = compareSemver(ver, want);
        bool ok = true;
        if (op == ">=") ok = cmp >= 0;
        else if (op == "<=") ok = cmp <= 0;
        else if (op == ">") ok = cmp > 0;
        else if (op == "<") ok = cmp < 0;
        else if (op == "=" || op.empty()) ok = cmp == 0;
        else if (op == "^") {
            int upper[3] = {want[0] == 0 ? 0 : want[0] + 1, want[0] == 0 ? want[1] + 1 : 0, 0};
            ok = cmp >= 0 && compareSemver(ver, upper) < 0;
        } else if (op == "~") {
            int upper[3] = {want[0], want[1] + 1, 0};
            ok = cmp >= 0 && compareSemver(ver, upper) < 0;
        }
        if (!ok) return false;
    }
    return true;
}
