        unsigned int chunk = ((unsigned char)text[i] << 16) | ((unsigned char)text[i + 1] << 8) | (unsigned char)text[i + 2];
        out += B64[(chunk >> 18) & 63];
        out += B64[(chunk >> 12) & 63];
        out += B64[(chunk >> 6) & 63];
        out += B64[chunk & 63];
        i += 3;
    }
