        int values[4];
        for (int k = 0; k < 4; k++) {
            char c = encoded[i + k];
            if (c == '=') {
                if (i + 4 != encoded.size() || k < 2) throw std::invalid_argument("bad padding");
                padding++;
                values[k] = 0;
                continue;
            }
            if (padding) throw std::invalid_argument("data after padding");
