std::vector<int> courseOrder(int n, const std::vector<std::pair<int,int>>& prerequisites) {
    std::vector<std::vector<int>> next(n);
    std::vector<int> indegree(n, 0);
    for (const auto& edge : prerequisites) {
        int course = edge.first, prereq = edge.second;
        next[prereq].push_back(course);
        indegree[course] += 1;
    }
    std::priority_queue<int, std::vector<int>, std::greater<int>> ready;
    for (int i = 0; i < n; i++) if (indegree[i] == 0) ready.push(i);
    std::vector<int> order;
    while (!ready.empty()) {
        int course = ready.top();
        ready.pop();
        order.push_back(course);
        for (int follower : next[course]) {
            if (--indegree[follower] == 0) ready.push(follower);
        }
    }
    if (static_cast<int>(order.size()) != n) return {};
    return order;
}
```

