std::string ticTacToeWinner(const std::vector<std::string>& board) {
    int xs = 0, os = 0;
    for (const auto& row : board) for (char c : row) { if (c == 'X') xs++; else if (c == 'O') os++; }
    auto line = [&](char who) {
        for (int i = 0; i < 3; i++) {
            if (board[i][0] == who && board[i][1] == who && board[i][2] == who) return true;
            if (board[0][i] == who && board[1][i] == who && board[2][i] == who) return true;
        }
        if (board[0][0] == who && board[1][1] == who && board[2][2] == who) return true;
        if (board[0][2] == who && board[1][1] == who && board[2][0] == who) return true;
        return false;
    };
    bool xw = line('X'), ow = line('O');
    if (xw && ow) return "Invalid";
    if (xw && xs != os + 1) return "Invalid";
    if (ow && xs != os) return "Invalid";
    if (xs != os && xs != os + 1) return "Invalid";
    if (xw) return "X";
    if (ow) return "O";
    for (const auto& row : board) for (char c : row) if (c == '.') return "Open";
    return "Draw";
}
