function paginate(items, page, pageSize) {
  if (!Number.isInteger(pageSize) || pageSize <= 0) throw new RangeError('pageSize must be positive');
  const total = items.length;
  const totalPages = Math.ceil(total / pageSize);
  let current = Math.trunc(page);
  if (!Number.isFinite(current) || current < 1) current = 1;
  if (totalPages > 0 && current > totalPages) current = totalPages;
  const start = (current - 1) * pageSize;
  return { items: items.slice(start, start + pageSize), page: current, pageSize, total, totalPages };
}
