function roundHalfUp(value, decimals) {
  const places = decimals === undefined ? 0 : decimals;
  if (!Number.isInteger(places) || places < 0 || places > 15) {
    throw new RangeError('decimals out of range');
  }
  const sign = value < 0 ? -1 : 1;
  const shifted = Math.abs(value).toFixed(places + 1);
  const truncated = Math.floor(Number(shifted));
  const rest = Number(shifted) - truncated;
  let rounded = truncated;
  if (rest >= 0.5) rounded += 1;
  return sign * Number((rounded / Math.pow(10, places)).toFixed(places));
}
