```cpp
int countTriplets(const std::vector<int>& values, int target) {
    std::vector<int> sorted(values);
    std::sort(sorted.begin(), sorted.end());
    int total = 0;
    int n = static_cast<int>(sorted.size());
    for (int i = 0; i + 2 < n; i++) {
        int left = i + 1, right = n - 1;
        while (left < right) {
            long long sum = static_cast<long long>(sorted[i]) + sorted[left] + sorted[right];
            if (sum == target) {
                if (sorted[left] == sorted[right]) {
                    int span = right - left + 1;
                    total += span * (span - 1) / 2;
                    break;
                }
                int leftCount = 1, rightCount = 1;
                while (left + 1 < right && sorted[left + 1] == sorted[left]) { left++; leftCount++; }
                while (right - 1 > left && sorted[right - 1] == sorted[right]) { right--; rightCount++; }
                total += leftCount * rightCount;
                left++;
                right--;
            } else if (sum < target) {
                left++;
            } else {
                right--;
            }
        }
    }
    return total;
}
