def bracket_score(text):
    stack = [0]
    for ch in text:
        if ch == "(":
            stack.append(0)
        elif ch == ")":
            if len(stack) < 2:
                raise ValueError("unbalanced")
            inner = stack.pop()
            stack[-1] += 1 if inner == 0 else 2 * inner
