class StatsCache<K, V> {
  private readonly capacity: number;
  private store = new Map<K, V>();
  private hitCount = 0;
  private missCount = 0;

  constructor(capacity: number) {
    if (!Number.isInteger(capacity) || capacity < 1) throw new RangeError('capacity must be positive');
    this.capacity = capacity;
  }

  get(key: K): V | undefined {
    if (this.store.has(key)) {
      this.hitCount += 1;
      return this.store.get(key);
    }
    this.missCount += 1;
    return undefined;
  }

  set(key: K, value: V): void {
    if (!this.store.has(key) && this.store.size >= this.capacity) {
      const oldest = this.store.keys().next();
      if (!oldest.done) this.store.delete(oldest.value);
    }
    this.store.set(key, value);
  }

  hits(): number { return this.hitCount; }
  misses(): number { return this.missCount; }
  hitRate(): number {
    const total = this.hitCount + this.missCount;
    return total === 0 ? 0 : this.hitCount / total;
  }
  size(): number { return this.store.size; }
}
