type Rules = Record<string, Record<string, string>>;

function createMachine(rules: Rules) {
  const can = (state: string, event: string): boolean =>
    Object.prototype.hasOwnProperty.call(rules, state) &&
    Object.prototype.hasOwnProperty.call(rules[state], event);

  const step = (state: string, event: string): string => {
    if (!can(state, event)) throw new Error('no transition');
    return rules[state][event];
  };

  const run = (state: string, events: string[]): string => {
    let current = state;
    for (const event of events) current = step(current, event);
    return current;
  };

  return { can, step, run };
}
