int firstMissingPositive(std::vector<int> values) {
    int n = static_cast<int>(values.size());
    for (int i = 0; i < n; i++) {
        while (values[i] > 0 && values[i] <= n && values[values[i] - 1] != values[i]) {
            std::swap(values[i], values[values[i] - 1]);
        }
    }
    for (int i = 0; i < n; i++) {
        if (values[i] != i + 1) return i + 1;
    }
    return n + 1;
}
