class AsyncQueue<T> {
  private values: T[] = [];
  private waiters: { resolve: (value: T) => void; reject: (error: Error) => void }[] = [];
  private closed = false;

  push(value: T): void {
    const waiter = this.waiters.shift();
    if (waiter) waiter.resolve(value);
    else this.values.push(value);
  }

  shift(): Promise<T> {
    if (this.values.length > 0) return Promise.resolve(this.values.shift() as T);
    if (this.closed) return Promise.reject(new Error('closed'));
    return new Promise<T>((resolve, reject) => this.waiters.push({ resolve, reject }));
  }

  close(): void {
    this.closed = true;
    if (this.values.length === 0) {
      for (const waiter of this.waiters.splice(0)) waiter.reject(new Error('closed'));
    }
  }

  size(): number {
    return this.values.length;
  }
}
