```typescript
class Trie {
  private root: { children: Map<string, any>; count: number } = { children: new Map(), count: 0 };

  insert(word: string): void {
    let node = this.root;
    for (const ch of word) {
      let next = node.children.get(ch);
      if (!next) {
        next = { children: new Map<string, any>(), count: 0 };
        node.children.set(ch, next);
      }
      node = next;
    }
    node.count += 1;
  }

  private walk(prefix: string): any {
    let node: any = this.root;
    for (const ch of prefix) {
      node = node.children.get(ch);
      if (!node) return undefined;
    }
    return node;
  }

  private collect(node: any, prefix: string, out: string[]): void {
    for (let i = 0; i < node.count; i++) out.push(prefix);
    for (const [ch, child] of node.children) this.collect(child, prefix + ch, out);
  }

  has(word: string): boolean {
    const node = this.walk(word);
    return node !== undefined && node.count > 0;
  }

  count(prefix: string): number {
    const node = this.walk(prefix);
    if (node === undefined) return 0;
    let total = 0;
    const stack = [node];
    while (stack.length > 0) {
      const current = stack.pop();
      total += current.count;
      for (const child of current.children.values()) stack.push(child);
    }
    return total;
  }

  words(): string[] {
    const out: string[] = [];
    this.collect(this.root, '', out);
    return out.sort();
  }
}
