#include <cassert>
#include <stdexcept>

std::vector<long long> dijkstra(int n, const std::vector<std::vector<std::pair<int,int>>>& adj, int source) {
    if (n < 1 || source < 0 || source >= n) throw std::out_of_range("bad arguments");
    const long long INF = (long long)4e18;
    std::vector<long long> dist(n, INF);
    dist[source] = 0;
    std::priority_queue<std::pair<long long,int>, std::vector<std::pair<long long,int>>, std::greater<std::pair<long long,int>>> pq;
    pq.push({0, source});
    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();
        if (d != dist[u]) continue;
        for (auto [v, w] : adj[u]) {
            if (d + w < dist[v]) {
                dist[v] = d + w;
                pq.push({dist[v], v});
            }
        }
    }
    for (auto& d : dist) if (d == INF) d = -1;
    return dist;
}
