#include <cassert>
#include <stdexcept>

class MinHeap {
public:
    void push(int value) {
        data_.push_back(value);
        size_t i = data_.size() - 1;
        while (i > 0) {
            size_t parent = (i - 1) / 2;
            if (data_[parent] <= data_[i]) break;
            std::swap(data_[parent], data_[i]);
            i = parent;
        }
    }

    int pop() {
        if (data_.empty()) throw std::out_of_range("empty heap");
        int result = data_.front();
        data_.front() = data_.back();
        data_.pop_back();
        siftDown(0);
        return result;
    }

    int top() const {
        if (data_.empty()) throw std::out_of_range("empty heap");
        return data_.front();
    }

    size_t size() const { return data_.size(); }
    bool empty() const { return data_.empty(); }

private:
    void siftDown(size_t i) {
        const size_t n = data_.size();
        while (true) {
            size_t best = i;
            size_t left = 2 * i + 1, right = 2 * i + 2;
            if (left < n && data_[left] < data_[best]) best = left;
            if (right < n && data_[right] < data_[best]) best = right;
            if (best == i) return;
            std::swap(data_[best], data_[i]);
            i = best;
        }
    }
    std::vector<int> data_;
};
