#include <cassert>
#include <stdexcept>

std::string rleEncode(const std::string& text) {
    std::string out;
    size_t i = 0;
    while (i < text.size()) {
        size_t j = i;
        while (j < text.size() && text[j] == text[i]) j++;
        out += std::to_string(j - i);
        out.push_back(text[i]);
        i = j;
    }
    return out;
}

std::string rleDecode(const std::string& encoded) {
    std::string out;
    size_t i = 0;
    while (i < encoded.size()) {
        if (!isdigit((unsigned char)encoded[i])) throw std::invalid_argument("expected count");
        long long count = 0;
        while (i < encoded.size() && isdigit((unsigned char)encoded[i])) {
            count = count * 10 + (encoded[i] - '0');
            i++;
        }
        if (i >= encoded.size()) throw std::invalid_argument("missing character");
        if (count == 0) throw std::invalid_argument("zero count");
        out.append((size_t)count, encoded[i]);
        i++;
    }
