std::vector<int> primesUpTo(int limit) {
    if (limit < 0) throw std::invalid_argument("negative limit");
    if (limit < 2) return {};
    std::vector<bool> composite((size_t)limit + 1, false);
    std::vector<int> primes;
    for (long long i = 2; i <= limit; i++) {
        if (composite[(size_t)i]) continue;
        primes.push_back((int)i);
        for (long long j = i * i; j <= limit; j += i) composite[(size_t)j] = true;
    }
    return primes;
}
