function addBusinessDays(start, count) {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(start));
  if (!match) throw new RangeError('bad date');
  if (!Number.isInteger(count)) throw new RangeError('count must be an integer');
  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  const date = new Date(Date.UTC(year, month - 1, day));
  if (date.getUTCFullYear() !== year || date.getUTCMonth() !== month - 1 || date.getUTCDate() !== day) {
    throw new RangeError('bad date');
  }
  const step = count < 0 ? -1 : 1;
  let remaining = Math.abs(count);
  while (remaining > 0) {
    date.setUTCDate(date.getUTCDate() + step);
    const weekday = date.getUTCDay();
    if (weekday !== 0 && weekday !== 6) remaining -= 1;
  }
