#include <cassert>
#include <stdexcept>

static long long parsePart(const std::string& text) {
    if (text.empty()) throw std::invalid_argument("empty part");
    size_t start = (text[0] == '-' || text[0] == '+') ? 1 : 0;
    if (start == text.size()) throw std::invalid_argument("bad number");
    for (size_t i = start; i < text.size(); i++) {
        if (text[i] < '0' || text[i] > '9') throw std::invalid_argument("bad number");
    }
    return std::stoll(text);
}

std::string rationalAdd(const std::string& a, const std::string& b) {
    auto split = [](const std::string& text) {
        size_t slash = text.find('/');
        if (slash == std::string::npos) throw std::invalid_argument("missing slash");
        long long num = parsePart(text.substr(0, slash));
        long long den = parsePart(text.substr(slash + 1));
        if (den == 0) throw std::invalid_argument("zero denominator");
        return std::make_pair(num, den);
    };
    auto left = split(a);
    auto right = split(b);
    long long num = left.first * right.second + right.first * left.second;
    long long den = left.second * right.second;
    if (den < 0) {
        num = -num;
        den = -den;
    }
    long long g = std::gcd(std::llabs(num), den);
    if (g == 0) g = 1;
    return std::to_string(num / g) + "/" + std::to_string(den / g);
}
