function minRooms(intervals) {
  for (const [start, end] of intervals) {
    if (start > end) throw new RangeError('bad interval');
  }
  const events = [];
  for (const [start, end] of intervals) {
    events.push([start, 1]);
    events.push([end, -1]);
  }
  events.sort((a, b) => (a[0] - b[0]) || (a[1] - b[1]));
  let rooms = 0;
  let best = 0;
  for (const event of events) {
    rooms += event[1];
    if (rooms > best) best = rooms;
  }
  return best;
}
