function digitsOf(text) {
  if (!/^[0-9]+$/.test(text)) throw new SyntaxError('digits only');
  return text.split('').map(ch => Number(ch));
}

function checksum(digits) {
  let total = 0;
  let double = false;
  for (let i = digits.length - 1; i >= 0; i--) {
    let value = digits[i];
    if (double) {
      value *= 2;
      if (value > 9) value -= 9;
    }
    total += value;
    double = !double;
  }
  return total;
}

function luhnValid(number) {
  const digits = digitsOf(number);
  if (digits.length < 2) return false;
  return checksum(digits) % 10 === 0;
}

function luhnCheckDigit(partial) {
  const digits = digitsOf(partial);
  for (let digit = 0; digit <= 9; digit++) {
    if (checksum([...digits, digit]) % 10 === 0) return digit;
  }
  return 0;
}
