                while (left + 1 < right && values[left + 1] == values[left]) { left++; leftCount++; }
                while (right - 1 > left && values[right - 1] == values[right]) { right--; rightCount++; }
                count += leftCount * rightCount;
                left++;
                right--;
            } else if (sum < target) {
                left++;
            } else {
                right--;
            }
        }
    }
    return count;
