std::vector<std::string> tokenizeMath(const std::string& text) {
    std::vector<std::string> tokens;
    size_t i = 0;
    while (i < text.size()) {
        char ch = text[i];
        if (ch == ' ' || ch == '\t' || ch == '\n' || ch == '\r') {
            i++;
        } else if (std::string("+-*/(),").find(ch) != std::string::npos) {
            tokens.push_back(std::string(1, ch));
            i++;
        } else if (ch >= '0' && ch <= '9') {
            size_t start = i;
            int dots = 0;
            while (i < text.size() && ((text[i] >= '0' && text[i] <= '9') || text[i] == '.')) {
                if (text[i] == '.') dots++;
                i++;
            }
            if (dots > 1) throw std::invalid_argument("bad number");
            tokens.push_back(text.substr(start, i - start));
        } else if (ch == '.') {
            size_t start = i;
            i++;
            int dots = 1;
            while (i < text.size() && ((text[i] >= '0' && text[i] <= '9') || text[i] == '.')) {
                if (text[i] == '.') dots++;
                i++;
            }
            if (dots > 1 || i == start + 1) throw std::invalid_argument("bad number");
            tokens.push_back(text.substr(start, i - start));
        } else if (isIdentStart(ch)) {
            size_t start = i;
            while (i < text.size() && (isIdentStart(text[i]) || (text[i] >= '0' && text[i] <= '9'))) i++;
            tokens.push_back(text.substr(start, i - start));
        } else {
            throw std::invalid_argument("bad character");
        }
    }
    return tokens;
}
