function buildTree(items) {
  const nodes = new Map();
  for (const item of items) {
    if (nodes.has(item.id)) throw new Error('duplicate id');
    nodes.set(item.id, { id: item.id, name: item.name, children: [] });
  }
  const roots = [];
  for (const item of items) {
    const node = nodes.get(item.id);
    if (item.parentId === null || item.parentId === undefined || !nodes.has(item.parentId)) {
      roots.push(node);
    } else {
      nodes.get(item.parentId).children.push(node);
    }
  }
  const sortTree = list => {
    list.sort((a, b) => a.id - b.id);
    for (const node of list) sortTree(node.children);
    return list;
  };
  return sortTree(roots);
}
