#include <cassert>
#include <stdexcept>

class Fenwick {
public:
    explicit Fenwick(int n) : n_(n), tree_(n + 1, 0) {
        if (n < 1) throw std::invalid_argument("n must be at least 1");
    }

    void add(int index, long long delta) {
        check(index);
        for (int i = index; i <= n_; i += i & -i) tree_[i] += delta;
    }

    long long prefix(int index) const {
        if (index < 0 || index > n_) throw std::out_of_range("bad index");
        long long total = 0;
        for (int i = index; i > 0; i -= i & -i) total += tree_[i];
        return total;
    }

    long long rangeSum(int left, int right) const {
        check(left);
        check(right);
        if (left > right) throw std::out_of_range("bad range");
        return prefix(right) - prefix(left - 1);
    }

private:
    void check(int index) const {
        if (index < 1 || index > n_) throw std::out_of_range("bad index");
    }
    int n_;
    std::vector<long long> tree_;
};
