#include <cassert>
#include <stdexcept>

int matrixChainCost(const std::vector<int>& dims) {
    if (dims.size() < 2) throw std::invalid_argument("need at least two dimensions");
    for (int dim : dims) if (dim < 1) throw std::invalid_argument("dimensions must be positive");
    const int n = (int)dims.size() - 1;
    std::vector<std::vector<long long>> best(n, std::vector<long long>(n, 0));
    for (int length = 2; length <= n; length++) {
        for (int i = 0; i + length - 1 < n; i++) {
            int j = i + length - 1;
            best[i][j] = (long long)4e18;
            for (int k = i; k < j; k++) {
                long long cost = best[i][k] + best[k + 1][j] + (long long)dims[i] * dims[k + 1] * dims[j + 1];
                if (cost < best[i][j]) best[i][j] = cost;
            }
        }
    }
    return (int)best[0][n - 1];
}
