class RunningMedian {
public:
    void add(int value) {
        if (low_.empty() || value <= low_.top()) low_.push(value);
        else high_.push(value);
        if (low_.size() > high_.size() + 1) {
            high_.push(low_.top());
            low_.pop();
        } else if (high_.size() > low_.size()) {
            low_.push(high_.top());
            high_.pop();
        }
    }

    double median() const {
        if (low_.empty()) throw std::out_of_range("empty");
        if (low_.size() == high_.size()) return (low_.top() + high_.top()) / 2.0;
        return (double)low_.top();
    }

private:
    std::priority_queue<int> low_;
    std::priority_queue<int, std::vector<int>, std::greater<int>> high_;
};
