class Ring<T> {
  private slots: (T | undefined)[];
  private start = 0;
  private count = 0;

  constructor(capacity: number) {
    if (!Number.isInteger(capacity) || capacity < 1) throw new RangeError('capacity must be positive');
    this.slots = new Array(capacity);
  }

  push(value: T): void {
    const index = (this.start + this.count) % this.slots.length;
    this.slots[index] = value;
    if (this.count < this.slots.length) this.count += 1;
    else this.start = (this.start + 1) % this.slots.length;
  }

  size(): number {
    return this.count;
  }

  isFull(): boolean {
    return this.count === this.slots.length;
  }

  toArray(): T[] {
    const out: T[] = [];
    for (let i = 0; i < this.count; i++) out.push(this.slots[(this.start + i) % this.slots.length] as T);
    return out;
  }
}
