struct ListNode {
    int value;
    ListNode* next;
};

ListNode* mergeLists(ListNode* a, ListNode* b) {
    ListNode* head = nullptr;
    ListNode** tail = &head;
    while (a != nullptr && b != nullptr) {
        if (a->value <= b->value) {
            *tail = a;
            a = a->next;
        } else {
            *tail = b;
            b = b->next;
        }
        tail = &((*tail)->next);
    }
    *tail = (a != nullptr) ? a : b;
    return head;
}
