bool hasCycle(int nodes, const std::vector<std::pair<int,int>>& edges) {
    if (nodes < 0) throw std::out_of_range("negative node count");
    std::vector<std::vector<int>> adjacency(nodes);
    for (auto [from, to] : edges) {
        if (from < 0 || from >= nodes || to < 0 || to >= nodes) throw std::out_of_range("bad edge");
        adjacency[from].push_back(to);
    }
    std::vector<char> colour(nodes, 0);
    for (int start = 0; start < nodes; start++) {
        if (colour[start] != 0) continue;
        std::vector<std::pair<int,size_t>> stack{{start, 0}};
        colour[start] = 1;
        while (!stack.empty()) {
            auto& [node, index] = stack.back();
            if (index < adjacency[node].size()) {
                int next = adjacency[node][index++];
                if (colour[next] == 1) return true;
                if (colour[next] == 0) {
                    colour[next] = 1;
                    stack.push_back({next, 0});
                }
            } else {
