#include <cassert>
#include <stdexcept>

long long countSetBits(long long limit) {
    if (limit < 0) throw std::invalid_argument("negative limit");
    long long total = 0;
    for (long long bit = 1; bit <= limit && bit > 0; bit <<= 1) {
        long long cycle = bit * 2;
        long long full = (limit + 1) / cycle;
        long long remainder = (limit + 1) % cycle;
        total += full * bit + std::max(0LL, remainder - bit);
    }
    return total;
}
