function parseDuration(text) {
  if (typeof text !== 'string' || text === '') throw new SyntaxError('empty duration');
  const units = { h: 3600, m: 60, s: 1 };
  const pattern = /^(?:(\d+)([hms]))+$/;
  if (!pattern.test(text)) throw new SyntaxError('bad duration');
  let total = 0;
  const seen = new Set();
  const matches = text.matchAll(/(\d+)([hms])/g);
  for (const match of matches) {
    const unit = match[2];
    if (seen.has(unit)) throw new SyntaxError('repeated unit');
    seen.add(unit);
    total += Number(match[1]) * units[unit];
  }
  return total;
}
