  values: Record<string, string | number | boolean | null | undefined>,
): string {
  const OPEN = '\u0001';
  const CLOSE = '\u0002';
  const guarded = template.split('{{').join(OPEN).split('}}').join(CLOSE);
  const replaced = guarded.replace(/\{([A-Za-z_][A-Za-z0-9_]*)\}/g, (match, name: string) => {
