#include <cassert>
#include <vector>
#include <stdexcept>

std::vector<std::vector<int>> matrix_multiply(const std::vector<std::vector<int>>& a,
                                              const std::vector<std::vector<int>>& b) {
    if (a.empty() || b.empty()) return {};
    const std::size_t inner = a[0].size();
    const std::size_t cols = b[0].size();
    for (const auto& row : a)
        if (row.size() != inner) throw std::invalid_argument("ragged left matrix");
    for (const auto& row : b)
        if (row.size() != cols) throw std::invalid_argument("ragged right matrix");
    if (b.size() != inner) throw std::invalid_argument("shape mismatch");
    std::vector<std::vector<int>> out(a.size(), std::vector<int>(cols, 0));
    for (std::size_t i = 0; i < a.size(); ++i)
        for (std::size_t k = 0; k < inner; ++k)
            for (std::size_t j = 0; j < cols; ++j)
                out[i][j] += a[i][k] * b[k][j];
    return out;
}
