#include <vector>

struct BstNode {
    int value;
    BstNode* left = nullptr;
    BstNode* right = nullptr;
    explicit BstNode(int v) : value(v) {}
};

BstNode* bst_insert(BstNode* root, int value) {
    if (root == nullptr) return new BstNode(value);
    BstNode* node = root;
    while (true) {
        if (value == node->value) return root;
        BstNode*& next = value < node->value ? node->left : node->right;
        if (next == nullptr) {
            next = new BstNode(value);
            return root;
        }
        node = next;
    }
}

std::vector<int> bst_inorder(const BstNode* root) {
    std::vector<int> out;
    std::vector<const BstNode*> stack;
    const BstNode* node = root;
    while (node != nullptr || !stack.empty()) {
        while (node != nullptr) {
            stack.push_back(node);
            node = node->left;
        }
        node = stack.back();
        stack.pop_back();
        out.push_back(node->value);
        node = node->right;
    }
    return out;
}

int bst_height(const BstNode* root) {
    if (root == nullptr) return 0;
    int left = bst_height(root->left);
    int right = bst_height(root->right);
    return 1 + (left > right ? left : right);
}

bool bst_contains(const BstNode* root, int value) {
    const BstNode* node = root;
    while (node != nullptr) {
        if (node->value == value) return true;
        node = value < node->value ? node->left : node->right;
    }
    return false;
}
