    for (std::size_t i = 0; i < values.size(); ++i) {
        while (!window.empty() && values[window.back()] <= values[i]) window.pop_back();
        window.push_back(i);
        if (window.front() + static_cast<std::size_t>(k) <= i) window.pop_front();
        if (i + 1 >= static_cast<std::size_t>(k)) out.push_back(values[window.front()]);
    }
    return out;
}
