std::vector<int> bfs_distances(const std::vector<std::vector<int>>& adjacency, int source) {
    if (adjacency.empty() || source < 0 || static_cast<std::size_t>(source) >= adjacency.size())
        throw std::out_of_range("bad source");
    std::vector<int> distance(adjacency.size(), -1);
    std::queue<int> pending;
    distance[source] = 0;
    pending.push(source);
    while (!pending.empty()) {
        int node = pending.front();
        pending.pop();
        for (int next : adjacency[node]) {
            if (next < 0 || static_cast<std::size_t>(next) >= adjacency.size())
                throw std::out_of_range("bad edge");
            if (distance[next] != -1) continue;
            distance[next] = distance[node] + 1;
            pending.push(next);
        }
    }
    return distance;
}
