class WordTrie {
  constructor() {
    this.root = { children: new Map(), end: false };
    this.size = 0;
  }

  add(word) {
    if (!word) return;
    let node = this.root;
    for (const ch of word) {
      if (!node.children.has(ch)) node.children.set(ch, { children: new Map(), end: false });
      node = node.children.get(ch);
    }
    if (!node.end) {
      node.end = true;
      this.size += 1;
    }
  }

  count(prefix) {
    let node = this.root;
    for (const ch of prefix) {
      if (!node.children.has(ch)) return 0;
      node = node.children.get(ch);
    }
    const stack = [node];
    let total = 0;
    while (stack.length > 0) {
      const current = stack.pop();
      if (current.end) total += 1;
      for (const child of current.children.values()) stack.push(child);
    }
    return total;
  }

  words() {
    const out = [];
    const walk = (node, prefix) => {
      if (node.end) out.push(prefix);
      for (const [ch, child] of node.children) walk(child, prefix + ch);
    };
    walk(this.root, '');
    return out.sort();
  }
}
