int max_activities(std::vector<std::pair<int, int>> slots) {
    for (const auto& [start, finish] : slots)
        if (start >= finish) throw std::invalid_argument("empty or reversed slot");
    std::sort(slots.begin(), slots.end(), [](const auto& a, const auto& b) {
        if (a.second != b.second) return a.second < b.second;
        return a.first < b.first;
    });
    int count = 0;
    int last = 0;
    bool started = false;
    for (const auto& [start, finish] : slots) {
        if (!started || start >= last) {
            ++count;
            last = finish;
            started = true;
        }
    }
    return count;
}
