#include <cassert>
#include <vector>
#include <stdexcept>

class CircularQueue {
public:
    explicit CircularQueue(int capacity) : buffer(static_cast<std::size_t>(capacity < 1 ? 0 : capacity)), limit(capacity) {
        if (capacity < 1) throw std::invalid_argument("capacity must be positive");
    }

    bool push(int value) {
        if (count == limit) return false;
        buffer[static_cast<std::size_t>((head + count) % limit)] = value;
        ++count;
        return true;
    }

    bool pop() {
        if (count == 0) return false;
        head = (head + 1) % limit;
        --count;
        return true;
    }

    int front() const {
        if (count == 0) throw std::out_of_range("empty queue");
        return buffer[static_cast<std::size_t>(head)];
    }

    int size() const { return count; }
    int capacity() const { return limit; }

private:
    std::vector<int> buffer;
    int limit = 0;
    int head = 0;
    int count = 0;
};
