#include <cassert>
#include <vector>
#include <stdexcept>
#include <limits>

long long max_window_sum(const std::vector<int>& values, int k) {
    if (k < 1) throw std::invalid_argument("k must be positive");
    if (static_cast<std::size_t>(k) > values.size() || values.empty())
        throw std::invalid_argument("window larger than input");
    long long window = 0;
    for (int i = 0; i < k; ++i) window += values[static_cast<std::size_t>(i)];
    long long best = window;
    for (std::size_t i = static_cast<std::size_t>(k); i < values.size(); ++i) {
        window += values[i] - values[i - static_cast<std::size_t>(k)];
        if (window > best) best = window;
    }
    return best;
}
