#include <vector>
#include <stdexcept>

long long fib_memo(int n) {
    if (n < 0) throw std::invalid_argument("negative index");
    static std::vector<long long> cache{0, 1};
    while (static_cast<int>(cache.size()) <= n) {
        const std::size_t size = cache.size();
        cache.push_back(cache[size - 1] + cache[size - 2]);
    }
    return cache[static_cast<std::size_t>(n)];
}
