#include <stdexcept>

static unsigned mask_for(int index) {
    if (index < 0 || index > 31) throw std::out_of_range("bit index out of range");
    return 1u << static_cast<unsigned>(index);
}

unsigned set_bit(unsigned mask, int index) { return mask | mask_for(index); }
unsigned clear_bit(unsigned mask, int index) { return mask & ~mask_for(index); }
bool has_bit(unsigned mask, int index) { return (mask & mask_for(index)) != 0u; }
unsigned toggle_bit(unsigned mask, int index) { return mask ^ mask_for(index); }

int count_bits(unsigned mask) {
    int count = 0;
    while (mask != 0u) {
        mask &= mask - 1u;
        ++count;
    }
    return count;
}
