#include <cassert>
#include <stdexcept>
#include <limits>

int isqrt(int value) {
    if (value < 0) throw std::invalid_argument("negative value");
    long long low = 0;
    long long high = static_cast<long long>(value);
    long long best = 0;
    while (low <= high) {
        const long long mid = low + (high - low) / 2;
        if (mid * mid <= value) {
            best = mid;
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return static_cast<int>(best);
}
