function expandField(text, min, max) {
  const out = new Set();
  for (const raw of text.split(',')) {
    const part = raw.trim();
    if (part === '') continue;
    let step = 1;
    let body = part;
    const slash = part.indexOf('/');
    if (slash !== -1) {
      step = Number(part.slice(slash + 1));
      body = part.slice(0, slash);
      if (!Number.isInteger(step) || step <= 0) throw new Error('bad step');
    }
    let start;
    let end;
    if (body === '*') {
      start = min;
      end = max;
    } else if (body.includes('-')) {
      const [a, b] = body.split('-');
      start = Number(a);
      end = Number(b);
    } else {
      start = Number(body);
      end = Number(body);
    }
    if (!Number.isInteger(start) || !Number.isInteger(end)) throw new Error('bad value');
    if (start > end) throw new Error('reversed range');
    if (start < min || end > max) throw new Error('out of bounds');
    for (let value = start; value <= end; value += step) out.add(value);
  }
  return Array.from(out).sort((a, b) => a - b);
}
