function once<T extends (...args: any[]) => any>(fn: T): T & { called: boolean } {
  let used = false;
  let result: any;
  const wrapper: any = (...args: any[]) => {
    if (!used) {
      used = true;
      result = fn(...args);
      wrapper.called = true;
    }
    return result;
  };
  wrapper.called = false;
  return wrapper;
}
```

