SIZE_UNITS = {'': 1, 'B': 1, 'KB': 1024, 'MB': 1024 ** 2, 'GB': 1024 ** 3, 'TB': 1024 ** 4}


def parse_size(text):
    cleaned = text.strip().replace(' ', '')
    if not cleaned:
        raise ValueError("empty size")
    digits = ''
    index = 0
    while index < len(cleaned) and (cleaned[index].isdigit() or cleaned[index] == '.'):
        digits += cleaned[index]
        index += 1
    unit = cleaned[index:].upper()
    if not digits or digits.count('.') > 1 or unit not in SIZE_UNITS:
        raise ValueError("bad size: " + text)
    return int(float(digits) * SIZE_UNITS[unit])
