function memoize(fn: (value: any, ...rest: any[]) => any): ((value: any, ...rest: any[]) => any) & { cacheSize: number } {
  const cache = new Map<any, any>();
  const wrapper: any = (value: any, ...rest: any[]) => {
    if (cache.has(value)) return cache.get(value);
    const result = fn(value, ...rest);
    cache.set(value, result);
    wrapper.cacheSize = cache.size;
    return result;
  };
  wrapper.cacheSize = 0;
  return wrapper;
}
```

