#include <cctype>

std::string title_first(const std::string& text) {
    std::string out;
    bool atStart = true;
    bool pendingSpace = false;
    for (char ch : text) {
        if (std::isspace(static_cast<unsigned char>(ch))) {
            if (!out.empty()) pendingSpace = true;
            continue;
        }
        if (pendingSpace) {
            out.push_back(' ');
            pendingSpace = false;
            atStart = true;
        }
        if (atStart && ch >= 'a' && ch <= 'z') ch = static_cast<char>(ch - 'a' + 'A');
        atStart = false;
        out.push_back(ch);
    }
    return out;
}
```

