```cpp
#include <cctype>

std::string mask_card(const std::string& number) {
    std::string out = number;
    int digits = 0;
    for (char ch : out) {
        if (std::isdigit(static_cast<unsigned char>(ch))) ++digits;
    }
    int remaining = digits;
    for (char& ch : out) {
        if (!std::isdigit(static_cast<unsigned char>(ch))) continue;
        if (remaining > 4) ch = '*';
        --remaining;
    }
    return out;
}
