```python
def rotate_digits(value):
    if value < 0:
        raise ValueError("non-negative value required")
    if value < 10:
        return value
    last = value % 10
    rest = value // 10
    digits = 1
    while rest >= 10 ** digits:
        digits += 1
    return last * (10 ** digits) + rest
